#!/usr/bin/env bash
# Демонстрация ЖДуши гостю (Анастасия) на 16–17.10: утренние новости + проход по всему меню.
# Агент zguest (гостевые ограничения: без Argus, файлы только гостю, копии владельцу). Повторный запуск без дублей.
#   bash ~/railway-monitor/anast_demo.sh
set -u
ID=207215298; AG=zguest; KIT=~/railway-monitor; SV="$KIT/saved_$AG"
LIST=$(openclaw automations list 2>/dev/null)
add() {  # add "<название>" "<мин> <час> <день> <мес> *" "<задание>"
  if grep -qF "$1" <<<"$LIST"; then echo "уже есть: $1"; return; fi
  openclaw automations create "$2" "$PRE $3 $POST" --name "$1" --tz Europe/Moscow --agent "$AG" --session isolated \
    --announce --channel telegram --account zhdusha --to "$ID" | grep -E '"name"|"nextRunAtMs"' | head -2
}
PRE="Демонстрация ЖДуши гостю (потенциальный клиент, тест 16–17.10). Покажи сам, без запроса."
POST="Первая строка ответа — название раздела меню. Последняя строка — как получить такое же самой (команда меню и пример). Ставки — только из открытых источников со ссылками; Argus, private/ и внутренние данные не упоминай и не используй, пометок об источнике ставок, кроме ссылок, не добавляй. Каждое событие и число — один раз. PDF: файл .md в $SV/, затем ~/pw/bin/python ~/aviation-monitor/share.py convert <файл.md> и python3 ~/railway-monitor/send.py --to $ID <файл.pdf>. Копию ответа владельцу — по гостевым правилам (send.py --copy), молча."
NEWS="Утренние новости ЖД-рынка за вчера строго по TEMPLATE.md и правилам AGENTS.md. Сначала запусти: python3 ~/railway-monitor/collector.py collect --days 2. PDF не нужен."

# 16.10, пятница
add "Гость ЖД: новости 16.10"      "45 8 16 10 *"  "$NEWS"
add "Гость ЖД: знакомство"         "0 10 16 10 *"  "Раздел /start. Не длиннее 8 строк: поздоровайся, ЖДуша — аналитик рынка полувагонов и крытых вагонов по открытым источникам. Сегодня и завтра ЖДуша сама покажет все разделы меню по очереди; кнопка «Меню» — слева от поля ввода; можно писать и обычным текстом. PDF не нужен."
add "Гость ЖД: полувагоны"         "0 11 16 10 *"  "Раздел /poluvagony: справка по рынку полувагонов строго по MARKET.md, коротко. В чат — вывод до 6 строк, полная справка — PDF."
add "Гость ЖД: ставки и парк"      "0 14 16 10 *"  "Разделы /rates, /loading, /balance одним сообщением до 15 строк: ставки аренды полувагонов и крытых и их динамика; погрузка по основным грузам; баланс парка (избыток или нехватка, куда движется). PDF не нужен."
add "Гость ЖД: справка ПГК"        "0 15 16 10 *"  "Раздел /profile: справка по компании ПГК (ИНН 7725806898) по правилам AGENTS.md «Справка по компании» — финансы, суды, имущество, класс риска. В чат — до 6 строк, справка — PDF."
add "Гость ЖД: прогноз"            "0 17 16 10 *"  "Раздел /forecast: прогноз на следующую неделю по полувагонам и крытым по разделу «Прогноз» AGENTS.md — ставки, грузопоток, баланс парка, риски. До 12 строк, PDF не нужен."
# 17.10, суббота
add "Гость ЖД: новости 17.10"      "45 8 17 10 *"  "$NEWS"
add "Гость ЖД: крытые"             "0 11 17 10 *"  "Раздел /krytye: справка по рынку крытых вагонов строго по MARKET.md, коротко. В чат — вывод до 6 строк, полная справка — PDF."
add "Гость ЖД: сравнение"          "0 14 17 10 *"  "Раздел /compare: сравни ПГК (ИНН 7725806898) и Атлант по правилам AGENTS.md — парк, финансы, долг, риски, рядом в таблице. В чат — до 8 строк, сравнение — PDF."
add "Гость ЖД: оперировать или сдавать" "0 16 17 10 *" "Раздел /lease: что выгоднее собственнику полувагонов сейчас — оперировать самому или сдавать в аренду: доход, расходы, риски, при каких ставках выбор меняется. До 12 строк, расчёт покажи по шагам. PDF не нужен."
add "Гость ЖД: отзыв"              "30 18 17 10 *" "Разделы /remember и /save — по одной строке, как ими пользоваться, с примером. Затем поблагодари за два дня теста и задай три вопроса для отзыва, пронумеруй: 1) что оказалось самым полезным; 2) чего не хватило или что неудобно; 3) пользовалась бы ЖДушей в работе и для каких задач. Ответы гостя сохраняй дословно с датой в $SV/feedback.md (дописывай). PDF не нужен."

echo "== Рассылки гостю:"
openclaw automations list 2>/dev/null | grep -F "Гость ЖД:"
echo "== Важно: Анастасия должна до 08:45 16.10 написать /start в @zhdusha_bot — иначе Telegram не даст боту ей писать."
